/**
 * dsh-provider-usage — server/schedule 域：到期判定纯函数（#768 D2，由 domain2/schedule/schedule.ts 搬入，零行为变更）。
 *
 * 语义（单一模型，三期统一）：
 * - 每期有「锚点触发时刻」：daily=当日 HH:MM（覆盖昨日全天）；weekly=周起点日 HH:MM（覆盖紧邻的前 7 天）；
 *   monthly=月内 dayOfMonth 日 HH:MM（覆盖上一自然月）；
 * - 候选窗口 = 最近一次「锚点 <= now」的触发；其覆盖区间由 runAt 唯一推导（均为已闭环的上一完整周期）；
 * - 幂等：lastRun[period] 存已生成的窗口键（日期序单调）；候选键 <= lastRun 即已扣期；
 * - 补跑：进程停机跨过锚点后重启，候选键 > lastRun 即自然补生成（只补最近一个，
 *   更早窗口不追溯——文档化口径）；
 * - DST 安全：全部经本地 Date 逐字段构造与逐日回退，禁缓存时区偏移、禁毫秒减法。
 */
import { dayKey } from "../../shared/interface.ts";
import { parseHHMM } from "../shared/interface.ts";
import type { ReportConfig, ReportPeriod } from "../config/interface.ts";

/** 一个到期报告的描述。 */
export interface DueReport {
  period: ReportPeriod;
  /** 窗口键（daily/weekly=日期 key；monthly=YYYY-MM）。幂等标记单位。 */
  key: string;
  /** 覆盖区间的本地日 key（闭区间）。 */
  startDay: string;
  endDay: string;
}

/** 某日 HH:MM 的本地时间戳。 */
function atTime(dateKey: string, time: string): number {
  const hm = parseHHMM(time) ?? { h: 22, m: 0 };
  const [y, mo, d] = dateKey.split("-").map(Number);
  return new Date(y, mo - 1, d, hm.h, hm.m, 0, 0).getTime();
}

/** 当日（now 所在日）HH:MM 的本地时间戳。 */
function todayAt(now: number, time: string): number {
  const d = new Date(now);
  return atTime(dayKey(d.getTime()), time);
}

/** 距 now 最近的一次「星期为 dow、时刻为 time」且 <= now 的本地时间戳（dow: 0=周日/1=周一）。 */
function lastWeekAnchor(now: number, dow: 0 | 1, time: string): number {
  const d = new Date(now);
  const back = (d.getDay() - dow + 7) % 7; // 距目标星期几的天数（0–6）
  d.setDate(d.getDate() - back);
  const anchorDate = atTime(dayKey(d.getTime()), time);
  if (anchorDate <= now) return anchorDate;
  // 锚点日当天时刻未到 → 退回上一周（本地逐日回退，DST 安全，禁毫秒减法）
  d.setDate(d.getDate() - 7);
  return atTime(dayKey(d.getTime()), time);
}

/** 距 now 最近的一次「m 月 d 日 HH:MM」且 <= now 的本地时间戳（跨月安全：逐月回退）。 */
function lastMonthAnchor(now: number, dayOfMonth: number, time: string): number {
  const d = new Date(now);
  const candidate = new Date(d.getFullYear(), d.getMonth(), dayOfMonth);
  const hm = parseHHMM(time) ?? { h: 9, m: 0 };
  candidate.setHours(hm.h, hm.m, 0, 0);
  if (candidate.getTime() <= now) return candidate.getTime();
  // 本月锚点未到 → 上月（setMonth 自动处理跨年/月长差异）
  const prev = new Date(d.getFullYear(), d.getMonth() - 1, dayOfMonth);
  prev.setHours(hm.h, hm.m, 0, 0);
  return prev.getTime();
}

/** 日 key 的 +n 天（本地逐日回退/推进，DST 安全）。 */
function addDays(dateKey: string, n: number): string {
  const [y, mo, d] = dateKey.split("-").map(Number);
  const dt = new Date(y, mo - 1, d);
  dt.setDate(dt.getDate() + n);
  return dayKey(dt.getTime());
}

/**
 * 给定周期的候选窗口（最近一次锚点 <= now 的触发及其覆盖区间）。
 * 不读 lastRun——幂等判定在 pendingReports。
 */
export function candidateWindow(period: ReportPeriod, cfg: ReportConfig, now: number): DueReport {
  if (period === "daily") {
    // 候选锚点日：最近一次 <= now 的触发日（已过当日时刻为今日，未过为昨日）
    const anchorDay = todayAt(now, cfg.daily.time) <= now ? dayKey(now) : addDays(dayKey(now), -1);
    // 覆盖上一自然日（昨日全天）：[anchorDay-1, anchorDay-1]
    const targetDay = addDays(anchorDay, -1);
    return { period, key: targetDay, startDay: targetDay, endDay: targetDay };
  }
  if (period === "weekly") {
    const runAt = lastWeekAnchor(now, cfg.weekly.weekStartsOn, cfg.weekly.time);
    const runDay = dayKey(runAt);
    // 覆盖紧邻前 7 天：[runDay-7, runDay-1]
    const end = addDays(runDay, -1);
    return { period, key: addDays(runDay, -7), startDay: addDays(runDay, -7), endDay: end };
  }
  // monthly
  const runAt = lastMonthAnchor(now, cfg.monthly.dayOfMonth, cfg.monthly.time);
  const runDate = new Date(runAt);
  // 覆盖上一自然月
  const start = new Date(runDate.getFullYear(), runDate.getMonth() - 1, 1);
  const end = new Date(runDate.getFullYear(), runDate.getMonth(), 0); // 本月 0 日 = 上月末
  const key = `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, "0")}`;
  return { period, key, startDay: dayKey(start.getTime()), endDay: dayKey(end.getTime()) };
}

/** last-run 纯面旧址（#768 A波4 re-export 门面）。
 *
 * canonical 已下沉 server/shared/last-run.ts（表达式逐字一致）；本文件仅作兼容门面；
 * 生产与测试一律经 server/shared/interface.ts 消费（同源纪律）；updateLastRun 有状态
 * 临界区留 server/schedule/store.ts 不动。
 */
export {
  LAST_RUN_SCHEMA,
  isClosedWindowRecord,
  deriveLastRun,
  alignLastRun,
} from "../shared/interface.ts";
export type { LastRunRecord } from "../shared/interface.ts";

/**
 * 已闭环的上一完整周期窗口（手动生成专用：恒定取已结束的上一周期，不受定时触发时刻是否到达的约束）。
 * - daily：恒为昨日全天 [today-1, today-1]；
 * - weekly：恒为上一完整周（覆盖距今最近已闭环的前 7 天）；
 * - monthly：恒为上一完整自然月 [上月1日, 上月末]。
 */
export function previousClosedWindow(
  period: ReportPeriod,
  cfg: ReportConfig,
  now: number,
): DueReport {
  if (period === "daily") {
    const yesterday = addDays(dayKey(now), -1);
    return { period, key: yesterday, startDay: yesterday, endDay: yesterday };
  }
  if (period === "weekly") {
    const d = new Date(now);
    const back = (d.getDay() - cfg.weekly.weekStartsOn + 7) % 7;
    d.setDate(d.getDate() - back);
    const currentWeekStart = dayKey(d.getTime());
    const start = addDays(currentWeekStart, -7);
    const end = addDays(currentWeekStart, -1);
    return { period, key: start, startDay: start, endDay: end };
  }
  // monthly
  const d = new Date(now);
  const start = new Date(d.getFullYear(), d.getMonth() - 1, 1);
  const end = new Date(d.getFullYear(), d.getMonth(), 0);
  const key = `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, "0")}`;
  return { period, key, startDay: dayKey(start.getTime()), endDay: dayKey(end.getTime()) };
}

/**
 * 计算当前到期的报告集合（调度 tick 数据源）：
 * 对每个启用期，取候选窗口；窗口键 > lastRun[period]（日期字典序）即到期。
 * lastRun 缺失视为从未生成（首次挂载即补生成最近窗口——补跑语义）。
 */
export function pendingReports(
  cfg: ReportConfig,
  now: number,
  lastRun: Partial<Record<ReportPeriod, string>>,
): DueReport[] {
  const out: DueReport[] = [];
  const periods: ReportPeriod[] = ["daily", "weekly", "monthly"];
  for (const period of periods) {
    if (!cfg[period].enabled) continue;
    const cand = candidateWindow(period, cfg, now);
    const done = lastRun[period];
    // 候选已触发过（含为更晚窗口生成过）→ 已扣期跳过
    if (done !== undefined && done >= cand.key) continue;
    out.push(cand);
  }
  return out;
}

/**
 * 首次启用周期的扣期预置（保存配置时调用，纯函数便于单测）。
 *
 * pendingReports 对 lastRun 缺失视为「补跑到期」——「停机跨锚点补跑」的既定语义；
 * 但「首次启用」不该立即生成最近窗口（用户预期：从下一个触发时刻开始）。故保存
 * 配置时对「本次 disabled→enabled 且 lastRun 无记录」的周期，预置 lastRun=当前
 * 候选键（当期视为已扣期），下个锚点自然触发。曾启用过（lastRun 已有值）的周期
 * 保持补跑语义不变。
 *
 * 返回新 lastRun 表与是否有变更；调用方 changed=true 时自行原子落盘，并须先写
 * lastRun 再 updateConfig（防下一轮 tick 读旧 lastRun 抢跑生成）。
 */
export function presetLastRunForNewlyEnabled(
  prev: ReportConfig,
  next: ReportConfig,
  now: number,
  lastRun: Partial<Record<ReportPeriod, string>>,
): { lastRun: Partial<Record<ReportPeriod, string>>; changed: boolean } {
  const out = { ...lastRun };
  let changed = false;
  for (const period of ["daily", "weekly", "monthly"] as const) {
    if (!next[period].enabled || prev[period].enabled) continue;
    if (out[period] !== undefined) continue; // 曾启用过：保持补跑语义
    out[period] = candidateWindow(period, next, now).key;
    changed = true;
  }
  return { lastRun: out, changed };
}

/**
 * dsh-provider-usage — server/schedule 域：极简调度器（#768 D2，由 domain2/schedule/scheduler.ts 搬入，零行为变更）。
 *
 * 形态（不引入 croner）：60s tick + 候选窗口对齐 + lastRun 幂等标记 +
 * 启动补跑（首轮 tick 即检查）。单飞互斥：生成超过 tick 间隔时后续 tick 跳过
 * （busy 标志），生成失败不推进 lastRun（下轮重试同一窗口，幂等不重复扣期）。
 * lastRun 持久化原语（读/写/临界区/迁移校准）见同域 store.ts——调度与执行
 * 经本域 interface.ts 门面消费同一原语（D2 前经 domain2/common 公共层，与本域构成叶循环）。
 */
import type { ReportConfig } from "../config/interface.ts";
import { pendingReports, type DueReport } from "./due.ts";
import { readLastRun, ensureLastRunMigrated } from "./store.ts";
import type { ScheduleIndexParser } from "./deps.ts";

export interface ReportSchedulerOptions {
  /** 存储根（historyRoot）。 */
  root: string;
  /** 当前配置（updateConfig 热更新）。 */
  config: ReportConfig;
  /** 到期回调（提交到任务队列，非阻塞；队列负责执行、幂等与 lastRun 推进）。 */
  onDue: (due: DueReport) => Promise<void>;
  /** 注入时钟（测试）。 */
  now?: () => number;
  /** tick 间隔（默认 60000；测试可缩短）。 */
  tickMs?: number;
  /** 诊断出口。 */
  warn?: (msg: string) => void;
  /**
   * index 解析端口（execute 域纯函数，组合根装配期注入，经启动校准透传
   * 给 store；缺省视同无事实，不校准——与 store“无 index”同语义）。
   */
  parseIndex?: ScheduleIndexParser;
}

export class ReportScheduler {
  private config: ReportConfig;
  private timer: ReturnType<typeof setInterval> | null = null;
  private disposed = false;
  private readonly root: string;
  private readonly onDue: (due: DueReport) => Promise<void>;
  private readonly now: () => number;
  private readonly tickMs: number;
  private readonly warn: (msg: string) => void;
  private readonly parseIndex?: ScheduleIndexParser;

  private constructor(opts: ReportSchedulerOptions) {
    this.root = opts.root;
    this.config = opts.config;
    this.onDue = opts.onDue;
    this.now = opts.now ?? Date.now;
    this.tickMs = opts.tickMs ?? 60_000;
    this.parseIndex = opts.parseIndex;
    this.warn = opts.warn ?? ((msg) => console.warn(`[dsh-provider-usage] report: ${msg}`));
  }

  /**
   * 启动：先做 lastRun 一致性校准（async，失败不影响调度），
   * 完成后立即跑首轮（启动补跑语义），随后固定间隔 tick。
   */
  static start(opts: ReportSchedulerOptions): ReportScheduler {
    const s = new ReportScheduler(opts);
    s.timer = setInterval(() => void s.tick(), s.tickMs);
    (s.timer as { unref?: () => void }).unref?.();
    void ensureLastRunMigrated(s.root, s.warn, s.parseIndex).finally(() => void s.tick());
    return s;
  }

  /** 热更新配置（下轮 tick 生效）。 */
  updateConfig(config: ReportConfig): void {
    this.config = config;
  }

  /**
   * 一轮检查：读 lastRun → 计算到期集合 → 逐个提交到任务队列（提交非阻塞，
   * 队列负责串行执行、幂等下沉与 lastRun 推进；同窗口已在队列中由队列去重吸收）。
   */
  async tick(): Promise<void> {
    if (this.disposed) return;
    try {
      const lastRun = await readLastRun(this.root);
      const due = pendingReports(this.config, this.now(), lastRun);
      for (const d of due) {
        try {
          await this.onDue(d);
        } catch (e: unknown) {
          this.warn(`${d.period} ${d.key} 提交失败：${e instanceof Error ? e.message : String(e)}`);
        }
      }
    } catch (e: unknown) {
      this.warn(`tick 异常：${e instanceof Error ? e.message : String(e)}`);
    }
  }

  /** 停止 tick（挂载清理；进行中的一轮自然完成——onDue 由宿主侧 await 语义决定）。 */
  dispose(): void {
    this.disposed = true;
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

/**
 * dsh-provider-usage — server/schedule 域：lastRun 持久化原语（#768 D2，
 * 由 domain2/common/last-run.ts 搬入，零行为变更）。
 *
 * per-root 临界区链唯一实现：读-改-写按 root 串行 + 写前重读全量快照，
 * 防多写方（保存配置 preset / 任务执行器推进）交错 lost-update。调度与执行
 * 经本域 interface.ts 门面消费同一原语（D2 前在 domain2/common，
 * 叶层与 domain2/schedule 构成值环；D2 后归属明确，环消失）。
 */
import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { join } from "node:path";
import type { ReportPeriod } from "../config/interface.ts";
import {
  alignLastRun,
  deriveLastRun,
  LAST_RUN_SCHEMA,
  type LastRunRecord,
} from "../shared/interface.ts";
import type { ScheduleIndexParser } from "./deps.ts";

/** lastRun 持久化文件。 */
function lastRunFile(root: string): string {
  return join(root, "reports", "last-run.json");
}

/** 读 lastRun（缺失/损坏返回空表）。导出供手动生成路由读改写复用。 */
export async function readLastRun(root: string): Promise<Partial<Record<ReportPeriod, string>>> {
  try {
    const raw = await readFile(lastRunFile(root), "utf8");
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: Partial<Record<ReportPeriod, string>> = {};
    for (const p of ["daily", "weekly", "monthly"] as const) {
      if (typeof parsed[p] === "string") out[p] = parsed[p];
    }
    return out;
  } catch {
    return {};
  }
}

/** 原子写 lastRun（tmp+rename，0600；带 schema 版本）。 */
export async function writeLastRun(
  root: string,
  state: Partial<Record<ReportPeriod, string>>,
): Promise<void> {
  const file = lastRunFile(root);
  await mkdir(join(root, "reports"), { recursive: true });
  const tmp = `${file}.${Date.now()}.tmp`;
  await writeFile(
    tmp,
    JSON.stringify({ ...state, schema: LAST_RUN_SCHEMA, updatedAt: Date.now() }),
    { mode: 0o600 },
  );
  await rename(tmp, file);
}

/**
 * 读 lastRun 原始全量（不应用 daily/weekly/monthly 白名单投影）——临界区写前重读
 * 专用：投影会静默丢弃非白名单键，round-trip 即 lost-update 的读取投影变体。
 */
async function readLastRunRaw(root: string): Promise<Record<string, unknown>> {
  try {
    const parsed: unknown = JSON.parse(await readFile(lastRunFile(root), "utf8"));
    return parsed !== null && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}

const lastRunChainByRoot = new Map<string, Promise<void>>();

/**
 * lastRun 单一临界区：读-改-写按 root 串行（per-root promise 链）+ 写前重读。
 * 所有 lastRun 的 read-modify-write 统一收敛到本函数——patch 只在临界区内、基于
 * 链上最新文件快照计算；同一 root 的更新按提交序串行落盘。
 */
export function updateLastRun(
  root: string,
  // 返回类型必须容纳 Promise：patch 允许实现成 async（用于模拟读-改-写之间的交错窗），
  // 下面 await 它的结果。只声明同步形态属「签名撒谎」——await 非 Promise 不会报错也不会
  // 等待，一旦有人照着类型写同步实现并依赖这里真的等了，就是静默的时序 bug（#764 命中）。
  patch: (
    prev: Partial<Record<ReportPeriod, string>>,
  ) => Partial<Record<ReportPeriod, string>> | Promise<Partial<Record<ReportPeriod, string>>>,
): Promise<void> {
  const prev = lastRunChainByRoot.get(root) ?? Promise.resolve();
  const run = async (): Promise<void> => {
    const cur = await readLastRunRaw(root);
    // await patch 结果：patch 允许挂起（async 形态模拟交错窗），不 await 会让
    // writeLastRun 收到未 resolve 的 Promise、spread 丢全部字段。
    await writeLastRun(root, await patch(cur as Partial<Record<ReportPeriod, string>>));
  };
  const next = prev.then(run, run);
  const tail = next.then(
    () => undefined,
    () => undefined,
  );
  lastRunChainByRoot.set(root, tail);
  return next;
}

/** 测试隔离钩子：返回指定 root 的临界区链尾（await 确定收敛）。 */
export function __lastRunChainForTests(root: string): Promise<void> | undefined {
  return lastRunChainByRoot.get(root);
}

/**
 * 启动时 lastRun 一致性保证：schema 旧 → 全量重算（deriveLastRun）；
 * schema 新 → 温和对齐（alignLastRun）；无 index 视作无事实，不动 lastRun。
 *
 * index 解析经 ScheduleIndexParser 端口注入（C 波单向化：本文件不直引
 * 执行域门面，纯函数实现由组合根装配期经调度器透传；缺端口视同无事实，
 * 不动 lastRun——与“无 index”同语义，不静默捏造校准值）。
 */
export async function ensureLastRunMigrated(
  root: string,
  warn?: (msg: string) => void,
  parseIndex?: ScheduleIndexParser,
): Promise<{
  changed: boolean;
  before: Partial<Record<ReportPeriod, string>>;
  after: Partial<Record<ReportPeriod, string>>;
}> {
  const diag = warn ?? ((msg: string) => console.warn(`[dsh-provider-usage] report: ${msg}`));
  try {
    const raw = await readFile(lastRunFile(root), "utf8").catch(() => null);
    if (raw === null) return { changed: false, before: {}, after: {} };
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const schema = typeof parsed.schema === "number" ? parsed.schema : 1;
    const before = await readLastRun(root);
    const indexRaw = await readFile(join(root, "reports", "index.jsonl"), "utf8").catch(() => null);
    if (indexRaw === null) return { changed: false, before, after: before };
    if (parseIndex === undefined) return { changed: false, before, after: before };
    const records = parseIndex(indexRaw) as LastRunRecord[];
    const after = schema < LAST_RUN_SCHEMA ? deriveLastRun(records) : alignLastRun(before, records);
    const changed = schema < LAST_RUN_SCHEMA || JSON.stringify(before) !== JSON.stringify(after);
    if (!changed) return { changed, before, after };
    // 唯一写面：校准落盘经 per-root 链（与 preset/执行器同链串行）。
    // 链内按最新快照重算（preset 同形）：链外预读定 changed，链内重算定落盘值。
    let written: Partial<Record<ReportPeriod, string>> | undefined;
    await updateLastRun(root, (cur) => {
      const fresh = schema < LAST_RUN_SCHEMA ? deriveLastRun(records) : alignLastRun(cur, records);
      written = fresh;
      return fresh;
    });
    const finalAfter = written ?? after;
    const msg =
      `schema ${schema}→${LAST_RUN_SCHEMA}：` +
      `${JSON.stringify(before)} → ${JSON.stringify(finalAfter)}`;
    diag(`lastRun 已按 index 事实校准（${msg}）`);
    return { changed, before, after: finalAfter };
  } catch (e: unknown) {
    diag(`lastRun 校准失败（保持原状）：${e instanceof Error ? e.message : String(e)}`);
    return { changed: false, before: {}, after: {} };
  }
}

/**
 * dsh-provider-usage — server/schedule 域：报告生成任务队列（#768 D2，由 domain2/schedule/tasks.ts 搬入，零行为变更）。
 *
 * 形态（方案定稿）：手动「立即生成」与定时 tick 共用的单一执行入口。
 * - 串行单飞：任务经 promise 链依次执行（等价于既有 reportMutex 语义），
 *   但「提交」与「执行」解耦——HTTP 只等入队，不等 LLM；
 * - 入队去重：同 (period,key) 已有 queued/running 任务时返回同一
 *   taskId，杜绝 tick 每 60s 提交与手动并发把同窗口任务堆成串行重复生成；
 * - 幂等下沉：本队列不判幂等——执行器（apply 层注入）负责「执行前重查 index，
 *   已有成功记录且非 force → 直接复用」，路由层另有前置短路，双保险；
 * - 不持久化：进程重启在途任务自然丢失，lastRun 未推进 → 下次 tick 按幂等
 *   判定补跑（收敛性由 lastRun 保证）；
 * - 资源：done/failed 任务按 TTL 修剪（默认 10min）与上限裁剪（默认 50）。
 */
import { randomUUID } from "node:crypto";
import type { ReportPeriod } from "../config/interface.ts";
import type { ReportMeta } from "../execute/interface.ts";

export type ReportTaskStatus = "queued" | "running" | "done" | "failed";

/** 任务输入（窗口 + force 标志）。 */
export interface ReportTaskInput {
  period: ReportPeriod;
  key: string;
  startDay: string;
  endDay: string;
  force?: boolean;
}

/** 任务状态记录（对外可查）。 */
export interface ReportTask {
  id: string;
  period: ReportPeriod;
  key: string;
  startDay: string;
  endDay: string;
  force: boolean;
  status: ReportTaskStatus;
  createdAt: number;
  updatedAt: number;
  /** done 后携带生成 meta（reused 时亦携带既有记录）。 */
  meta?: ReportMeta;
  /** done 且 meta 来自幂等短路复用（非新生成）时为 true——status 响应透传，客户端对称提示「已复用」。 */
  reused?: boolean;
  /** failed 时携带脱敏错误信息。 */
  error?: string;
}

/** 执行器结果：meta 可为既有记录（reused 短路）或新生成。 */
export interface ReportTaskResult {
  meta?: ReportMeta;
  reused?: boolean;
}

export interface ReportTaskQueueOptions {
  /** 串行执行器：负责幂等下沉、生成、lastRun 推进；抛错 → 任务 failed（不推进 lastRun）。 */
  executor: (input: ReportTaskInput) => Promise<ReportTaskResult>;
  /** 注入时钟（测试）。 */
  now?: () => number;
  /** 诊断出口。 */
  warn?: (msg: string) => void;
  /** done/failed 任务留存（默认 600000 = 10min）。 */
  ttlMs?: number;
  /** 任务表上限（默认 50）。 */
  maxTasks?: number;
}

export class ReportTaskQueue {
  private readonly tasks = new Map<string, ReportTask>();
  private tail: Promise<unknown> = Promise.resolve();
  private readonly executor: (input: ReportTaskInput) => Promise<ReportTaskResult>;
  private readonly now: () => number;
  private readonly warn: (msg: string) => void;
  private readonly ttlMs: number;
  private readonly maxTasks: number;

  constructor(opts: ReportTaskQueueOptions) {
    this.executor = opts.executor;
    this.now = opts.now ?? Date.now;
    this.warn = opts.warn ?? ((msg: string) => console.warn(`[dsh-provider-usage] report: ${msg}`));
    this.ttlMs = opts.ttlMs ?? 600_000;
    this.maxTasks = opts.maxTasks ?? 50;
  }

  /**
   * 提交任务（非阻塞，立即返回 taskId）。
   * 同 (period,key) 已有 queued/running 任务 → 返回既有 taskId（去重）；
   * 新提交 force=true 且既有任务 force=false → 升级既有任务 force（重新生成
   * 语义不因去重丢失）。
   */
  submit(input: ReportTaskInput): { taskId: string; existing: boolean } {
    for (const t of this.tasks.values()) {
      if (
        (t.status === "queued" || t.status === "running") &&
        t.period === input.period &&
        t.key === input.key
      ) {
        if (input.force === true && t.force === false) t.force = true;
        return { taskId: t.id, existing: true };
      }
    }
    const now = this.now();
    const task: ReportTask = {
      id: randomUUID(),
      period: input.period,
      key: input.key,
      startDay: input.startDay,
      endDay: input.endDay,
      force: input.force === true,
      status: "queued",
      createdAt: now,
      updatedAt: now,
    };
    this.tasks.set(task.id, task);
    this.tail = this.tail.then(() => this.run(task)).catch(() => {});
    this.prune();
    return { taskId: task.id, existing: false };
  }

  /** 查询任务；未知 taskId → undefined。 */
  get(taskId: string): ReportTask | undefined {
    return this.tasks.get(taskId);
  }

  private async run(task: ReportTask): Promise<void> {
    task.status = "running";
    task.updatedAt = this.now();
    try {
      const res = await this.executor({
        period: task.period,
        key: task.key,
        startDay: task.startDay,
        endDay: task.endDay,
        force: task.force,
      });
      task.status = "done";
      task.meta = res.meta;
      task.reused = res.reused === true;
      task.updatedAt = this.now();
    } catch (e: unknown) {
      // 失败（含执行器内部已捕获后的再抛）不推进 lastRun：执行器约定
      task.status = "failed";
      task.error = e instanceof Error ? e.message : String(e);
      task.updatedAt = this.now();
      this.warn(`task ${task.period} ${task.key} 执行失败：${task.error}`);
    }
  }

  /** 修剪：超龄 done/failed 淘汰 + 超上限时裁剪最旧的 done/failed（queued/running 不裁）。 */
  private prune(): void {
    const cutoff = this.now() - this.ttlMs;
    for (const [id, t] of this.tasks) {
      if ((t.status === "done" || t.status === "failed") && t.updatedAt < cutoff)
        this.tasks.delete(id);
    }
    while (this.tasks.size > this.maxTasks) {
      let oldest: string | null = null;
      let oldestAt = Number.POSITIVE_INFINITY;
      for (const [id, t] of this.tasks) {
        if (t.status !== "done" && t.status !== "failed") continue; // 在途任务不裁
        if (t.createdAt < oldestAt) {
          oldestAt = t.createdAt;
          oldest = id;
        }
      }
      if (oldest === null) break;
      this.tasks.delete(oldest);
    }
  }
}

/**
 * dsh-provider-usage — server/shared last-run 纯面叶子（#768 A波4）。
 *
 * LAST_RUN_SCHEMA / LastRunRecord / isClosedWindowRecord / deriveLastRun /
 * alignLastRun 的 canonical 落点（由 server/schedule/due.ts 纯面逐字下沉，
 * 零行为变更；updateLastRun 有状态临界区留 schedule 域不动）。
 * 共享层准入：无单一所有者（schedule 启动校准 + upgrade 迁移双消费）、
 * 零值进口域（仅值引 src/shared 日界 + type-only 引 ReportPeriod）、≥2 正当消费者。
 * 目录外经 server/shared/interface.ts 消费，旧址 server/schedule/due.ts 保留
 * re-export 门面（生产与测试同源，均经 shared 门面）。
 */
import { dayKey } from "../../shared/interface.ts";
import type { ReportPeriod } from "../config/interface.ts";

/** last-run.json schema 版本（v2 = daily 候选键语义统一为「已闭环窗口」）。 */
export const LAST_RUN_SCHEMA = 2;

/** 迁移/推导输入：index.jsonl 单条记录的最小字段（鸭子类型，避免与 runner 循环依赖）。 */
export interface LastRunRecord {
  period: ReportPeriod;
  key: string;
  generatedAt: number;
  endDay: string;
  ok: boolean;
}

/**
 * 「窗口已闭环」判定：生成时刻所在本地日 > 窗口结束日。
 * 纯字符串日期序（dayKey(generatedAt) > endDay），与 addDays/dayKey 同源构造：
 * - 旧语义 daily「当天」记录（发起日 = endDay 当天）恒不闭环（窗口未走完）；
 * - 新语义 daily「昨天」记录（发起日 = endDay+1）恒闭环；
 * - weekly/monthly 生成时刻天然晚于窗口结束。
 * 禁用时间戳 + 23:59:59 构造：Date.parse("…T23:59:59") 无时区按 UTC 解析，
 * UTC+8 下会把新语义闭环记录误判为未闭环（无限补跑）且 CI 时区盲区不可测。
 */
export function isClosedWindowRecord(r: LastRunRecord): boolean {
  return r.ok === true && dayKey(r.generatedAt) > r.endDay;
}

/**
 * 由 index.jsonl 事实推导 lastRun（迁移 + 长期一致性口径）：
 * 「lastRun = 各期最新已闭环窗口的键」——与读侧投影同构：index 是事实日志，
 * lastRun 是投影，任何时刻可重算（幂等、可重放、自动修复旧语义污染键）。
 * - 有闭环记录 → 取最晚键（已扣期语义不变：候选键 <= lastRun 即跳过）；
 * - 无闭环记录（从未生成 / index 清理过 / 旧语义「当天」污染）→ 不设键（恢复补跑，
 *   最多重生成最近一期，幂等安全）。
 */
export function deriveLastRun(records: LastRunRecord[]): Partial<Record<ReportPeriod, string>> {
  const out: Partial<Record<ReportPeriod, string>> = {};
  for (const period of ["daily", "weekly", "monthly"] as const) {
    let maxKey: string | undefined;
    for (const r of records) {
      if (r.period !== period || !isClosedWindowRecord(r)) continue;
      if (maxKey === undefined || r.key > maxKey) maxKey = r.key;
    }
    if (maxKey !== undefined) out[period] = maxKey;
  }
  return out;
}

/**
 * schema 已新（>=2）时的温和校准：仅「该期 index 存在已闭环记录」才把 lastRun
 * 对齐到最新闭环键（修旧语义污染/遮蔽事故的滞后与超前），否则保留原值——
 * 保护「首次启用预置扣期」键（preset 键在 index 中天然无对应记录，
 * 全量重算会删掉它导致首次启用被立即补跑）。
 */
export function alignLastRun(
  lastRun: Partial<Record<ReportPeriod, string>>,
  records: LastRunRecord[],
): Partial<Record<ReportPeriod, string>> {
  const out = { ...lastRun };
  for (const period of ["daily", "weekly", "monthly"] as const) {
    let maxKey: string | undefined;
    for (const r of records) {
      if (r.period !== period || !isClosedWindowRecord(r)) continue;
      if (maxKey === undefined || r.key > maxKey) maxKey = r.key;
    }
    if (maxKey !== undefined) out[period] = maxKey;
  }
  return out;
}

/**
 * dsh-provider-usage — server/shared 时间解析叶子（#768 A波1）。
 *
 * parseHHMM 的 canonical 落点（由 server/config/normalize.ts:33 纯下沉，表达式逐字一致，
 * 零行为变更）。共享层准入：无单一所有者（config 归一化 + schedule 到期判定双消费）、
 * 零依赖纯函数（零 import）、≥2 正当消费者。目录外经 server/shared/interface.ts 消费，
 * 旧址 server/config/normalize.ts 保留 re-export 门面（生产与测试同源，均经 shared 门面）。
 */

/** HH:MM 解析（非法返回 null；notifier quiet-hours 同款严格性）。 */
export function parseHHMM(v: unknown): { h: number; m: number } | null {
  if (typeof v !== "string") return null;
  const m = /^(\d{1,2}):(\d{2})$/.exec(v.trim());
  if (m === null) return null;
  const h = Number(m[1]);
  const mm = Number(m[2]);
  if (!Number.isInteger(h) || !Number.isInteger(mm) || h < 0 || h > 23 || mm < 0 || mm > 59)
    return null;
  return { h, m: mm };
}

