// ---------------------------------------------------------------- #629 P2 executor 复用 → 队列记录 + status 响应透传 reused

describe("#629 P2 executor 复用 → 队列记录 + status 响应透传 reused", () => {
  let taskDefined: boolean;
  let taskReused: boolean | undefined;
  let payloadStatus: string;
  let payloadReused: boolean | undefined;
  let payload2Status: string;
  let payload2Reused: boolean | undefined;

  beforeAll(async () => {
    // executor 幂等短路（返回 reused:true）→ task.done 且 task.reused=true →
    // handleReportStatus 响应携带 reused（客户端轮询路径「已复用」提示的数据源）
    const queue = new ReportTaskQueue({
      executor: async () => ({
        meta: {
          period: "daily",
          key: "2026-09-05",
          startDay: "2026-09-05",
          endDay: "2026-09-05",
          generatedAt: 1,
          ok: true,
          provider: "",
          model: "",
          durationMs: 0,
        },
        reused: true,
      }),
      warn: () => {},
    });
    const sub = queue.submit({
      period: "daily",
      key: "2026-09-05",
      startDay: "2026-09-05",
      endDay: "2026-09-05",
    });
    const task = await pollUntil(
      () => {
        const t = queue.get(sub.taskId);
        return t?.status === "done" ? t : undefined;
      },
      5000,
      2,
    );
    taskDefined = task !== undefined;
    taskReused = task?.reused;
    // status 路由响应透传 reused（直调 handler：包 {handler} 适配 helpers.callHandler
    // 的三参形态，补 context 实参——handleReportStatus 仅消费 reportQueue 字段）
    const payload = await callHandler<{ status: string; reused?: boolean }>(
      {
        handler: (req, res) =>
          handleReportStatus(
            req as IncomingMessage,
            res as ServerResponse,
            {
              reportQueue: queue,
            } as unknown as ReportRoutesContext,
          ),
      },
      {
        socket: { remoteAddress: "127.0.0.1" },
        headers: { host: "127.0.0.1:3080", "sec-fetch-site": "same-origin" },
        method: "GET",
        url: `/api/dsh-provider-usage/reports/generate/status?taskId=${sub.taskId}`,
      },
    );
    payloadStatus = payload.status;
    payloadReused = payload.reused;

    // 对照：非复用任务（reused 缺省）不携带 reused 字段
    const queue2 = new ReportTaskQueue({
      executor: async () => ({
        meta: {
          period: "daily",
          key: "2026-09-06",
          startDay: "2026-09-06",
          endDay: "2026-09-06",
          generatedAt: 2,
          ok: true,
          provider: "",
          model: "",
          durationMs: 0,
        },
      }),
      warn: () => {},
    });
    const sub2 = queue2.submit({
