    mkdirSync(join(root, "reports"), { recursive: true });
    writeFileSync(join(root, "reports", "index.jsonl"), `${JSON.stringify(seeded)}\n`);
  };
  const fakeTrend = {
    buckets: () => [],
    dirRows: () => [],
    hourRows: () => [],
